def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        components = path[1:].split('/')
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent directory
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component to the current path
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if this path is a symlink
        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the target of the symlink
            target = links[candidate]

            # Resolve the target relative to the directory containing the link
            if target.startswith('/'):
                # Absolute target
                current = '/'
                new_components = target[1:].split('/')
            else:
                # Relative target - relative to the directory containing the link
                link_dir = candidate.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'
                current = link_dir
                new_components = target.split('/')

            # Replace the remaining components with the new components
            components = new_components + components[i+1:]
            i = 0
            continue

        # Not a symlink, just move to this path
        current = candidate
        i += 1

    # Return the result with no trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current

